import React, { useEffect, useState, useContext } from 'react';
import { useParams, Link } from 'react-router-dom';
import { useSpring, animated } from '@react-spring/web';
import { getCampaigns } from '../../services/campaignService';
import { AuthContext } from '../../context/AuthContext';
import { createDonation, getDonationHistory } from '../../services/donateService';
import API_BASE_URL from '../../config/api';
import { Swiper, SwiperSlide } from 'swiper/react';
import 'swiper/css';
import 'swiper/css/navigation';
import 'swiper/css/pagination';
import { Navigation, Pagination } from 'swiper/modules';

const DonationDetailPage = () => {
  const { id } = useParams();
  const [campaign, setCampaign] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [donationHistory, setDonationHistory] = useState([]);
  const { user } = useContext(AuthContext);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState({ amount: '', name: '', email: '' });
  const [donationError, setDonationError] = useState(null);

  const fadeIn = useSpring({
    from: { opacity: 0 },
    to: { opacity: 1 },
    config: { duration: 1000 },
  });

  // Ambil data campaign dan riwayat donasi saat komponen dimuat
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        // 1. Ambil data campaign
        const campaignData = await getCampaigns();
        const campaignsArray = Array.isArray(campaignData) ? campaignData : campaignData.campaigns || campaignData.data || [];
        
        // Perbaikan: Pastikan tipe data ID sama (String) saat dibandingkan
        const selectedCampaign = campaignsArray.find((campaign) => String(campaign._id) === String(id));
        
        if (selectedCampaign) {
          setCampaign(selectedCampaign);
        } else {
          setError("Data campaign tidak ditemukan.");
        }
      } catch (error) {
        console.error("Error fetching campaign data:", error);
        setError("Gagal memuat data campaign.");
      } finally {
        setLoading(false);
      }

      // 2. Ambil riwayat donasi (dipisah agar jika error, halaman utama tidak crash)
      if (user) {
        try {
          const historyData = await getDonationHistory();
          setDonationHistory(historyData);
        } catch (historyError) {
          console.error("Error fetching donation history:", historyError);
        }
      }
    };

    fetchData();
  }, [id, user]);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const openModal = () => {
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setFormData({ amount: '', name: '', email: '' });
    setDonationError(null);
  };

  const handleDonationSubmit = async (e) => {
    e.preventDefault();

    if (!formData.amount || isNaN(formData.amount) || formData.amount <= 0) {
      setDonationError("Masukkan jumlah donasi yang valid.");
      return;
    }

    if (!user && (!formData.name.trim() || !formData.email.trim())) {
      setDonationError("Masukkan nama dan email untuk melanjutkan donasi.");
      return;
    }

    try {
      const donationPayload = {
        amount: formData.amount,
        name: user ? user.username : formData.name.trim(),
        email: user ? user.username : formData.email.trim(),
      };

      const response = await createDonation(id, donationPayload);
      if (response.success) {
        window.location.href = response.paymentUrl;
      } else {
        setDonationError("Gagal membuat donasi. Silakan coba lagi.");
      }
    } catch (error) {
      console.error("Error creating donation:", error);
      setDonationError(error.message || "Terjadi kesalahan saat membuat donasi.");
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <p className="text-gray-600">Memuat data campaign...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <p className="text-red-600">{error}</p>
      </div>
    );
  }

  if (!campaign) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <p className="text-gray-600">Data campaign tidak ditemukan.</p>
      </div>
    );
  }

  return (
    <animated.div style={fadeIn} className="min-h-screen bg-gray-50 pt-20">
      <main className="container mx-auto px-4 sm:px-6 lg:px-20 py-12">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div>
            <Swiper
              modules={[Navigation, Pagination]}
              spaceBetween={10}
              slidesPerView={1}
              navigation
              pagination={{ clickable: true }}
              loop={true}
              className="rounded-lg shadow-lg"
            >
              {/* Perbaikan: Cek apakah campaign.images ada dan tidak kosong sebelum di-map */}
              {campaign?.images && campaign.images.length > 0 ? (
                campaign.images.map((image, index) => (
                  <SwiperSlide key={index}>
                    <img
                      src={`${API_BASE_URL}${image}`}
                      alt={`Campaign Image ${index + 1}`}
                      className="w-full h-64 lg:h-96 object-cover rounded-lg"
                    />
                  </SwiperSlide>
                ))
              ) : (
                <SwiperSlide>
                  <div className="w-full h-64 lg:h-96 bg-gray-200 flex items-center justify-center rounded-lg">
                    <p className="text-gray-500">Tidak ada gambar tersedia</p>
                  </div>
                </SwiperSlide>
              )}
            </Swiper>
          </div>

          <div className="bg-white p-6 lg:p-8 rounded-lg shadow-md">
            <span className="text-sm text-green-600 bg-green-100 px-3 py-1 rounded-full">
              {campaign.category}
            </span>
            <h2 className="text-2xl lg:text-3xl font-bold text-gray-800 mt-4">{campaign.title}</h2>
            
            {/* Progress Bar & Stats */}
            <div className="mt-6">
              <div className="flex justify-between text-sm font-semibold text-gray-700 mb-2">
                <span>Rp {campaign.collected?.toLocaleString() || 0} terkumpul</span>
                <span>Target: Rp {campaign.target?.toLocaleString() || 0}</span>
              </div>
              <div className="w-full bg-gray-200 rounded-full h-3">
                <div
                  className="bg-green-500 h-3 rounded-full"
                  style={{ width: `${Math.min((campaign.collected / campaign.target) * 100, 100)}%` }}
                ></div>
              </div>
              <div className="flex justify-between text-xs text-gray-500 mt-2">
                <span>{Math.round((campaign.collected / campaign.target) * 100) || 0}% tercapai</span>
                <span>{campaign.daysLeft || 0} hari lagi</span>
              </div>
            </div>

            <p className="text-gray-600 mt-6 text-lg leading-relaxed">
              {campaign.detail}
            </p>
            <button
              onClick={openModal}
              className="w-full mt-8 px-6 py-4 bg-green-600 text-white text-lg font-bold rounded-xl shadow-lg hover:bg-green-700 transition-all duration-300"
            >
              Donasi Sekarang
            </button>
          </div>
        </div>

        {/* Riwayat Donasi */}
        <section className="mt-12">
          <h3 className="text-2xl font-bold text-gray-800">Riwayat Donasi</h3>
          <div className="mt-6 space-y-6">
            {user ? (
              donationHistory.filter((donation) => donation.paymentStatus === 'success').length > 0 ? (
                donationHistory
                  .filter((donation) => donation.paymentStatus === 'success')
                  .map((donation) => (
                    <div key={donation._id} className="flex justify-between items-center border-b pb-4">
                      <div className="flex items-center space-x-4">
                        <div className="w-10 h-10 bg-gray-100 rounded-full flex items-center justify-center">
                          <i className="fas fa-user text-gray-600"></i>
                        </div>
                        <div>
                          <p className="text-gray-800 font-semibold">Anda</p>
                          <p className="text-sm text-gray-600">
                            {new Date(donation.createdAt).toLocaleDateString()}
                          </p>
                          <p className="text-sm text-gray-600">
                            Status: {donation.paymentStatus}
                          </p>
                        </div>
                      </div>
                      <p className="text-green-600 font-bold">
                        Rp. {donation.amount.toLocaleString()}
                      </p>
                    </div>
                  ))
              ) : (
                <p className="text-gray-600">Belum ada donasi yang berhasil.</p>
              )
            ) : (
              <p className="text-gray-600">
                <Link to="/login" className="text-green-600 hover:underline">Login</Link> untuk melihat riwayat donasi kamu.
              </p>
            )}
          </div>
        </section>
      </main>

      {/* Modal untuk Donasi */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-lg shadow-lg w-full max-w-md">
            <h2 className="text-2xl font-bold text-gray-800 mb-6">Donasi Sekarang</h2>
            <form onSubmit={handleDonationSubmit}>
              <div className="mb-5">
                <label className="block text-gray-700 text-sm font-semibold mb-2">
                  Pilih Nominal Donasi (Rp)
                </label>
                <div className="grid grid-cols-2 gap-3 mb-4">
                  {[50000, 100000, 250000, 500000].map((nominal) => (
                    <button
                      key={nominal}
                      type="button"
                      onClick={() => setFormData({ ...formData, amount: String(nominal) })}
                      className={`px-4 py-3 rounded-xl font-semibold border-2 transition-all duration-200 ${
                        formData.amount === String(nominal)
                          ? 'bg-green-600 text-white border-green-600 shadow-md'
                          : 'bg-white text-gray-700 border-gray-300 hover:border-green-400 hover:bg-green-50'
                      }`}
                    >
                      Rp {nominal.toLocaleString()}
                    </button>
                  ))}
                </div>
                <label className="block text-gray-700 text-sm font-semibold mb-2" htmlFor="amount">
                  Atau Masukkan Nominal Lain
                </label>
                <input
                  type="number"
                  id="amount"
                  value={formData.amount}
                  onChange={(e) => setFormData({ ...formData, amount: e.target.value })}
                  className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-green-500 transition"
                  placeholder="Masukkan nominal sendiri"
                />
              </div>
              {!user && (
                <>
                  <div className="mb-5">
                    <label className="block text-gray-700 text-sm font-semibold mb-2" htmlFor="name">
                      Nama Lengkap
                    </label>
                    <input
                      type="text"
                      id="name"
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                      className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-green-500 transition"
                      placeholder="Masukkan nama lengkap"
                      required
                    />
                  </div>
                  <div className="mb-5">
                    <label className="block text-gray-700 text-sm font-semibold mb-2" htmlFor="email">
                      Email
                    </label>
                    <input
                      type="email"
                      id="email"
                      value={formData.email}
                      onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                      className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-green-500 transition"
                      placeholder="Email untuk bukti transfer"
                      required
                    />
                  </div>
                </>
              )}
              {donationError && (
                <p className="text-red-500 text-sm mb-4 bg-red-50 p-2 rounded">{donationError}</p>
              )}
              <div className="flex justify-end space-x-3 mt-6">
                <button
                  type="button"
                  onClick={closeModal}
                  className="px-6 py-3 bg-gray-100 text-gray-700 font-semibold rounded-xl hover:bg-gray-200 transition"
                >
                  Batal
                </button>
                <button
                  type="submit"
                  className="px-6 py-3 bg-green-600 text-white font-semibold rounded-xl hover:bg-green-700 transition"
                >
                  Lanjut Pembayaran
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </animated.div>
  );
};

export default DonationDetailPage;